          }}>

            {/* Top group: eyebrow + headline */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'clamp(1.5rem, 2.5vw, 2.5rem)' }}>

              {/* Eyebrow */}
              <div
                data-hero-reveal
